{
  "name": "罗德与施瓦茨 NRVS 功率计",
  "name_en": "Rohde & Schwarz NRVS Power Meter",
  "manufacturer": "Rohde & Schwarz",
  "description": "用于射频/微波功率测量的台式功率计，可读取测量频率、功率幅度、传感器信息以及校准相关数据，适合实验室中的功率检测与传感器校验管理。",
  "description_en": "A benchtop RF/microwave power meter for power measurement. It can read or set measurement frequency and query power amplitude, sensor information, and calibration-related data for laboratory power measurement and sensor verification workflows.",
  "actions": [
    {
      "action_name": "auto-frequency",
      "description": "获取或设置测量频率。",
      "description_en": "Get or set the measurement frequency."
    },
    {
      "action_name": "auto-amplitude",
      "description": "读取当前功率幅度测量值。",
      "description_en": "Read the current power amplitude measurement."
    },
    {
      "action_name": "auto-calibration_data",
      "description": "读取校准数据。",
      "description_en": "Read calibration data."
    },
    {
      "action_name": "auto-calibration_dates",
      "description": "读取校准日期信息。",
      "description_en": "Read calibration date information."
    },
    {
      "action_name": "auto-sensor",
      "description": "读取已连接功率传感器的信息。",
      "description_en": "Read information about the connected power sensor."
    }
  ],
  "tag_hints": [
    "RF power measurement",
    "microwave power meter",
    "power sensor",
    "calibration data",
    "frequency setting",
    "benchtop test instrument"
  ]
}

